import{_ as a,o as t,c as i,a2 as e}from"./chunks/framework.BZO4qERu.js";const k=JSON.parse('{"title":"快速开始","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guides/quick-start.md","filePath":"zh/guides/quick-start.md","lastUpdated":1788855895000}'),l={name:"zh/guides/quick-start.md"};function h(n,s,o,r,p,d){return t(),i("div",null,[...s[0]||(s[0]=[e(`<h1 id="快速开始" tabindex="-1">快速开始 <a class="header-anchor" href="#快速开始" aria-label="Permalink to &quot;快速开始&quot;">​</a></h1><p>大约十分钟即可跑通 Memoh:部署服务端、登录、添加模型供应商、创建第一个机器人,并把它接到一个聊天平台。</p><div class="tip custom-block"><p class="custom-block-title">不想自托管?</p><p><a href="https://memoh.ai" target="_blank" rel="noreferrer">Memoh Cloud</a> 提供与开源版一致的托管服务。登录后可直接跳到 <a href="#第-3-步添加模型供应商">第 3 步</a>。</p></div><h2 id="前置条件" tabindex="-1">前置条件 <a class="header-anchor" href="#前置条件" aria-label="Permalink to &quot;前置条件&quot;">​</a></h2><ul><li>一台安装了 <strong>Docker</strong> 与 <strong>Docker Compose</strong> 的 Linux 服务器或工作站。</li><li>至少一个 LLM 供应商的 API Key(OpenAI、Anthropic、DeepSeek、智谱……),或本地 Ollama。</li><li>浏览器可以访问服务器的 <strong>8080</strong>(API)与 <strong>8082</strong>(Web UI)端口。</li></ul><h2 id="第-1-步-部署服务端" tabindex="-1">第 1 步:部署服务端 <a class="header-anchor" href="#第-1-步-部署服务端" aria-label="Permalink to &quot;第 1 步:部署服务端&quot;">​</a></h2><p>一行安装脚本会拉取镜像、生成 <code>config.toml</code>,并用 Docker Compose 启动全部组件:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://memoh.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sh</span></span></code></pre></div><p>中国大陆用户可启用镜像加速:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://memoh.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> USE_CN_MIRROR</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">true</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sh</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">不要用 <code>sudo</code> 运行整个安装脚本</p><p>当前用户不在 <code>docker</code> 组时,脚本会自行调用 <code>sudo docker</code>。</p></div><p>想手动部署?克隆仓库后执行:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/felinics/Memoh.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Memoh</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> conf/app.docker.toml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config.toml</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 编辑 config.toml(管理员密码、JWT 密钥等)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span></span></code></pre></div><p>完成后会看到类似输出:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>🌐 Web UI:      http://localhost:8082</span></span>
<span class="line"><span>🔌 API:         http://localhost:8080</span></span>
<span class="line"><span>🔑 Admin login: admin / &lt;你的密码&gt;</span></span></code></pre></div><p>生产环境加固、反向代理与升级方式见 <a href="/zh/self-hosted/docker.html">服务端部署</a>。</p><h2 id="第-2-步-登录" tabindex="-1">第 2 步:登录 <a class="header-anchor" href="#第-2-步-登录" aria-label="Permalink to &quot;第 2 步:登录&quot;">​</a></h2><p>打开 <code>http://&lt;你的服务器&gt;:8082</code>,使用安装时设置的管理员账号登录(<code>conf/app.docker.toml</code> 中的默认值为 <code>admin</code> / <code>admin123</code>)。登录后请立即在 <strong>设置 → 账户</strong> 中修改密码。</p><h2 id="第-3-步-添加模型供应商" tabindex="-1">第 3 步:添加模型供应商 <a class="header-anchor" href="#第-3-步-添加模型供应商" aria-label="Permalink to &quot;第 3 步:添加模型供应商&quot;">​</a></h2><ol><li>在侧边栏进入 <strong>供应商</strong>,点击 <strong>添加供应商</strong>。</li><li>选择模板(OpenAI、Anthropic、Gemini、DeepSeek、智谱、OpenRouter、Ollama……)并填入 API Key。</li><li>进入该供应商,<strong>同步</strong> 或手动添加至少一个对话模型。</li></ol><p>更多细节与客户端类型见 <a href="/zh/integrations/providers/llm.html">LLM 供应商</a>。</p><h2 id="第-4-步-创建第一个机器人" tabindex="-1">第 4 步:创建第一个机器人 <a class="header-anchor" href="#第-4-步-创建第一个机器人" aria-label="Permalink to &quot;第 4 步:创建第一个机器人&quot;">​</a></h2><ol><li>进入 <strong>机器人 → 新建机器人</strong>,填写名称与显示名。</li><li>在机器人的 <strong>通用</strong> 标签页中选择刚添加的对话模型。</li><li>点击机器人的 <strong>聊天</strong> 按钮打个招呼。收到回复即说明链路已打通。</li></ol><p>每个机器人都有独立的工作区、记忆与设置,各标签页说明见 <a href="/zh/guides/bot.html">机器人</a>。</p><h2 id="第-5-步-接入聊天平台" tabindex="-1">第 5 步:接入聊天平台 <a class="header-anchor" href="#第-5-步-接入聊天平台" aria-label="Permalink to &quot;第 5 步:接入聊天平台&quot;">​</a></h2><ol><li>打开机器人的 <strong>渠道</strong> 标签页,点击 <strong>添加</strong>。</li><li>选择平台(Telegram、Discord、Slack、飞书、钉钉、企业微信、QQ、LINE、Matrix、Misskey……)并填写平台凭据。</li><li>在该平台上给机器人发消息。第一条消息会创建会话;输入 <code>/help</code> 查看可用的斜杠命令。</li></ol><p>各平台的详细配置见 <a href="/zh/integrations/channels/">渠道</a>。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><table tabindex="0"><thead><tr><th>目标</th><th>阅读</th></tr></thead><tbody><tr><td>让机器人跨会话记住用户</td><td><a href="/zh/guides/memory.html">记忆</a></td></tr><tr><td>运行定时或周期任务</td><td><a href="/zh/guides/schedule.html">定时任务</a></td></tr><tr><td>赋予机器人文件、Shell 与浏览器能力</td><td><a href="/zh/guides/container.html">Workspace</a>、<a href="/zh/guides/computers.html">Computers</a></td></tr><tr><td>通过 MCP 服务器添加工具</td><td><a href="/zh/guides/mcp.html">MCP</a></td></tr><tr><td>教会机器人可复用的流程</td><td><a href="/zh/guides/skills.html">Skills</a>、<a href="/zh/guides/supermarket.html">Supermarket</a></td></tr><tr><td>控制谁可以和机器人对话</td><td><a href="/zh/guides/access.html">访问控制</a></td></tr><tr><td>在 Mac 上用桌面版运行</td><td><a href="/zh/self-hosted/desktop.html">Desktop</a></td></tr></tbody></table>`,29)])])}const g=a(l,[["render",h]]);export{k as __pageData,g as default};
